    "id": "various-artists-sympophony-a-collection-of-american-power-pop",
    "slug": "various-artists-sympophony-a-collection-of-american-power-pop",
    "title": "SymPOPhony, A Collection Of American Power Pop",
    "artist": "Various Artists",
    "label": "Not Lame Records",
    "format": "CD",
    "genre": "Jan-May 1996",
    "date": "02.10.1996",
